import{_ as t,o as a,c as i,ah as n}from"./chunks/framework.BMM80GXQ.js";const p=JSON.parse('{"title":"AI Agent","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/ai-agent/index.md","filePath":"2.0/ai-agent/index.md","lastUpdated":1775051911000}'),o={name:"2.0/ai-agent/index.md"};function r(s,e,l,c,h,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to &quot;AI Agent&quot;">​</a></h1><p>The AI Agent is a built-in, natural language interface for managing your PIM operations directly through conversation. Instead of navigating menus and forms, you can simply describe what you need in plain English, and the AI Agent will carry out the task for you.</p><p>With <strong>23 built-in PIM tools</strong> accessible via chat, the AI Agent transforms how you interact with your product data. Whether you need to create products, enrich descriptions, check data quality, or perform bulk updates, the AI Agent understands your intent and executes the right operations.</p><h2 id="key-capabilities" tabindex="-1">Key Capabilities <a class="header-anchor" href="#key-capabilities" aria-label="Permalink to &quot;Key Capabilities&quot;">​</a></h2><h3 id="product-management" tabindex="-1">Product Management <a class="header-anchor" href="#product-management" aria-label="Permalink to &quot;Product Management&quot;">​</a></h3><p>Create, update, search, and bulk edit products without leaving the chat interface. The AI Agent can handle everything from single product updates to large-scale bulk operations across your catalog.</p><h3 id="data-quality-completeness" tabindex="-1">Data Quality &amp; Completeness <a class="header-anchor" href="#data-quality-completeness" aria-label="Permalink to &quot;Data Quality &amp; Completeness&quot;">​</a></h3><p>Run data quality scans to identify products with missing or incomplete information. The AI Agent can generate completeness reports and highlight exactly which fields need attention.</p><h3 id="auto-enrichment" tabindex="-1">Auto-Enrichment <a class="header-anchor" href="#auto-enrichment" aria-label="Permalink to &quot;Auto-Enrichment&quot;">​</a></h3><p>Let the AI Agent automatically generate missing product descriptions, meta titles, meta descriptions, and other SEO-related fields. This is especially useful when onboarding large catalogs with sparse data.</p><h3 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h3><p>Perform bulk transformations across multiple products at once. Update attributes, reassign categories, or modify product data in batch, all through simple conversational commands.</p><h3 id="task-planning" tabindex="-1">Task Planning <a class="header-anchor" href="#task-planning" aria-label="Permalink to &quot;Task Planning&quot;">​</a></h3><p>For complex, multi-step operations, the AI Agent can break down your request into a structured plan and execute each step in sequence, keeping you informed throughout the process.</p><h2 id="real-time-streaming-sse" tabindex="-1">Real-Time Streaming (SSE) <a class="header-anchor" href="#real-time-streaming-sse" aria-label="Permalink to &quot;Real-Time Streaming (SSE)&quot;">​</a></h2><p>The AI Agent uses <strong>Server-Sent Events (SSE)</strong> to stream responses in real time. As the agent processes your request, you see the output appear progressively, giving you immediate feedback rather than waiting for the entire response to complete.</p><h2 id="conversation-persistence" tabindex="-1">Conversation Persistence <a class="header-anchor" href="#conversation-persistence" aria-label="Permalink to &quot;Conversation Persistence&quot;">​</a></h2><p>All chat sessions are stored in the database, so your conversation history is preserved across page refreshes and browser sessions. You can pick up right where you left off, and the AI Agent retains the context of your previous messages within the same session.</p><h2 id="acl-authorization" tabindex="-1">ACL Authorization <a class="header-anchor" href="#acl-authorization" aria-label="Permalink to &quot;ACL Authorization&quot;">​</a></h2><p>Every one of the 23 tools available to the AI Agent respects the <strong>Access Control List (ACL)</strong> permissions configured for your admin role. If your role does not have permission to perform a certain action (for example, deleting products), the AI Agent will not execute that action on your behalf. This ensures that the AI Agent operates strictly within the boundaries of your assigned permissions.</p><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h2><p>To ensure fair usage and system stability, the AI Agent enforces a rate limit of <strong>30 requests per minute</strong> per user. If you exceed this limit, you will receive a notification to wait before sending additional messages.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The AI Agent is most effective when you provide clear, specific instructions. For example, instead of saying &quot;fix my products,&quot; try &quot;update all products in the Electronics category that are missing a meta description.&quot;</p></div>',23)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
